import socket, concurrent.futures
def probe(p):
    s=socket.socket(); s.settimeout(0.04)
    try:
        if s.connect_ex(('127.0.0.1',p)) == 0: return p
    finally: s.close()
open_ports=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
    for p in ex.map(probe, range(1,65536), chunksize=64):
        if p is not None: open_ports.append(p)
print('OPEN_PORTS', open_ports)
for p in open_ports:
    s=socket.socket(); s.settimeout(1.0)
    try:
        s.connect(('127.0.0.1',p))
        s.sendall(b'GET / HTTP/1.0\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n')
        data=s.recv(4096)
        print('PORT',p,'HTTP_PROBE',repr(data[:3000]))
    except Exception as e:
        print('PORT',p,'BANNER',repr(str(e)))
    finally: s.close()
